INSERT INTO public.knowledge_articles (title, content, summary, category, emoji, read_time_minutes, tags, thumbnail_url, is_published, author_name, view_count, created_at, updated_at)
SELECT * FROM (VALUES
('Complete Vaccination Schedule for Dogs in India', 'A proper vaccination schedule is vital for canine health in India. Essential shots include Rabies, DHPP (Distemper, Hepatitis, Parvovirus, and Parainfluenza), and Leptospirosis. Consult your vet to ensure your puppy receives boosters at 8, 12, and 16 weeks to build strong immunity.', 'Everything you need to know about vaccinating your dog, from puppyhood to adult boosters — India-specific schedule.', 'Canine', '💉', 7, ARRAY['dogs','vaccination','India','health']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T10:00:00Z'::timestamptz, '2026-05-14T10:00:00Z'::timestamptz),
('Understanding Cat Body Language: The Tail', 'A cat''s tail is a high-speed communication tool. A high, upright tail usually signals confidence and a friendly greeting. Conversely, a puffed-up tail indicates fear or aggression, while a low tuck suggests anxiety. Learning these subtle cues helps strengthen the bond between you and your cat.', 'Decode what your feline friend is trying to tell you through the movement and position of their tail.', 'Feline', '🐈', 5, ARRAY['cats','behavior','communication','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T10:05:00Z'::timestamptz, '2026-05-14T10:05:00Z'::timestamptz),
('Nitrogen Cycle Basics for New Aquarists', 'Before adding fish, you must establish a biological filter through the nitrogen cycle. Beneficial bacteria convert toxic ammonia from fish waste into nitrites and then into less harmful nitrates. This process usually takes 4-6 weeks and is the foundation of a healthy aquatic environment.', 'The most important concept in fish keeping: how to cycle your tank safely before adding fish.', 'Aquatic', '🐠', 8, ARRAY['fish','aquarium','water quality','what to expect']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T10:10:00Z'::timestamptz, '2026-05-14T10:10:00Z'::timestamptz),
('Safe Fruits and Vegetables for Parrots', 'Fresh produce like kale, carrots, and apples (without seeds) are excellent additions to a parrot''s diet. However, never feed them avocado, chocolate, or onions, as these are highly toxic to birds. Diversity in food ensures your feathered friend gets the vitamins necessary for vibrant plumage.', 'A guide to nutritional fresh snacks that are safe for your avian companions.', 'Avian', '🦜', 4, ARRAY['birds','nutrition','food','safety']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T10:15:00Z'::timestamptz, '2026-05-14T10:15:00Z'::timestamptz),
('Choosing the Right Cage for Your Hamster', 'Hamsters require significant floor space to run and burrow; vertical height is less important than total square inches. Avoid cages with wire floors which can cause ''bumblefoot'' and ensure the bar spacing is small enough to prevent escapes. A minimum of 450 square inches is recommended for most breeds.', 'Why floor space matters more than height when picking a home for small rodents.', 'Small Pet', '🐹', 6, ARRAY['hamsters','housing','safety','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T10:20:00Z'::timestamptz, '2026-05-14T10:20:00Z'::timestamptz),
('The Importance of Positive Reinforcement Training', 'Positive reinforcement involves using treats, praise, or play to encourage desired behaviors. This method builds trust and a love for learning in pets across all species. Science shows that pets trained with rewards are more likely to retain information and exhibit less stress-related behaviors.', 'Why rewarding good behavior is more effective than punishing the bad in pet training.', 'General', '🎾', 6, ARRAY['training','behavior','psychology','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T10:25:00Z'::timestamptz, '2026-05-14T10:25:00Z'::timestamptz),
('Summer Safety: Preventing Heatstroke in Dogs', 'Heatstroke is a medical emergency for dogs. Always provide access to shade and fresh water, and avoid walking your pet during peak sun hours (11 AM - 4 PM). Watch for heavy panting or glazed eyes, and use cooling mats or damp towels to help regulate their temperature if they seem overheated.', 'Essential tips for keeping your canine companion cool during the intense Indian summer months.', 'Canine', '☀️', 5, ARRAY['dogs','safety','summer','health']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T11:00:00Z'::timestamptz, '2026-05-14T11:00:00Z'::timestamptz),
('Transitioning Your Cat to a New Home', 'Cats are territorial and find moving very stressful. Start by keeping them in one ''safe room'' with familiar bedding and toys for the first few days. Gradually allow them to explore the rest of the house as they become more confident, ensuring all windows are secured to prevent escape attempts in the new environment.', 'A step-by-step guide to reducing feline stress during a relocation or house move.', 'Feline', '🏠', 6, ARRAY['cats','life','moving','behavior']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T11:10:00Z'::timestamptz, '2026-05-14T11:10:00Z'::timestamptz),
('The Dangers of Overfeeding Aquarium Fish', 'Overfeeding is a leading cause of aquarium failure. Uneaten food decays, causing ammonia spikes and algae blooms that can suffocate your fish. Most fish only need to be fed what they can consume in two minutes; implementing a ''fasting day'' once a week can also help keep their digestive systems healthy.', 'Why less is often more when it comes to maintaining a healthy aquatic ecosystem.', 'Aquatic', '🥣', 4, ARRAY['fish','food','maintenance','health']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T11:20:00Z'::timestamptz, '2026-05-14T11:20:00Z'::timestamptz),
('Teaching Your Parrot to ''Step Up''', 'The ''step up'' command is the cornerstone of bird training. Use a favorite treat to lure your parrot onto your finger or a perch while calmly saying the command. Consistent, short training sessions of 5-10 minutes daily will build the trust necessary for your bird to move comfortably between locations.', 'Mastering the foundational command for safe handling and bonding with your bird.', 'Avian', '✋', 7, ARRAY['birds','training','bonding','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T11:30:00Z'::timestamptz, '2026-05-14T11:30:00Z'::timestamptz),
('Common Household Hazards for Rabbits', 'Rabbits are natural chewers, making electrical cords a major hazard in any home. Use plastic cord protectors and keep houseplants out of reach, as many—like lilies and aloe—are toxic. Ensure all flooring is non-slip to prevent ''splay leg'' injuries during their zoomies.', 'Identifying the hidden dangers in your home to create a rabbit-safe environment.', 'Small Pet', '⚠️', 6, ARRAY['rabbits','safety','home','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T11:40:00Z'::timestamptz, '2026-05-14T11:40:00Z'::timestamptz),
('First Aid Kit Essentials for Every Pet Owner', 'A basic pet first aid kit should include antiseptic wipes, gauze, adhesive tape, and a digital thermometer. Additionally, keep a list of emergency vet contacts and a bottle of saline solution for flushing eyes or wounds. Being prepared can make all the difference in the critical minutes following an accident.', 'A checklist of items you should always have on hand for pet emergencies.', 'General', '📦', 8, ARRAY['safety','health','emergency','what to expect']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T11:50:00Z'::timestamptz, '2026-05-14T11:50:00Z'::timestamptz),
('Introduction to Iwagumi Style Aquascaping', 'The Iwagumi style relies on an odd number of rocks to create a sense of natural balance. The ''Oyaishi'' or primary stone acts as the focal point, while smaller ''Sanzun'' stones provide support. This style typically uses low-growing carpet plants like Monte Carlo or Dwarf Hairgrass to maintain a sense of scale and serenity.', 'Master the Japanese art of rock placement and minimalist aquatic design.', 'Aquatic', '🪨', 9, ARRAY['aquascaping','design','iwagumi','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T21:40:00Z'::timestamptz, '2026-05-14T21:40:00Z'::timestamptz),
('Amano Shrimp: The Ultimate Cleanup Crew', 'Amano shrimp are legendary for their ability to consume hair algae and leftover fish food. They are generally peaceful but should not be kept with large, aggressive fish that might view them as a snack. Ensure your aquarium is well-oxygenated, as these shrimp are sensitive to low oxygen levels and high copper concentrations.', 'Why every planted tank needs Amano shrimp to manage algae and debris.', 'Aquatic', '🦐', 6, ARRAY['shrimp','maintenance','algae','safety']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T21:42:00Z'::timestamptz, '2026-05-14T21:42:00Z'::timestamptz),
('Caring for Fancy Guppies: A Beginner''s Guide', 'Fancy guppies are prized for their vibrant tails and ease of care. They prefer slightly alkaline water and benefit from a varied diet of flakes and frozen foods. Because they are prolific breeders, it is often best for beginners to start with a ''males-only'' tank to avoid an unplanned population explosion.', 'Tips for keeping these colorful and active fish thriving in your home aquarium.', 'Aquatic', '🐟', 5, ARRAY['guppies','beginner','fish','what to expect']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T21:44:00Z'::timestamptz, '2026-05-14T21:44:00Z'::timestamptz),
('The Role of Driftwood in Planted Tanks', 'Driftwood like Bogwood or Mopani adds a rustic, aged look to aquariums while providing surfaces for moss and ferns to grow. Be aware that most wood releases tannins, which can slightly tint your water yellow or brown and lower the pH. Boiling the wood before use can help reduce this ''tanning'' effect.', 'How adding natural wood impacts water chemistry and aesthetic appeal.', 'Aquatic', '🪵', 7, ARRAY['decor','water chemistry','plants','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T21:46:00Z'::timestamptz, '2026-05-14T21:46:00Z'::timestamptz),
('Low-Tech vs. High-Tech Planted Aquariums', 'Low-tech tanks rely on moderate lighting and natural fish waste for nutrients, making them easier to maintain. High-tech tanks utilize pressurized CO2 and intense lighting to achieve rapid growth and lush colors. Beginners should start low-tech to master the basics of water balance before investing in complex equipment.', 'Deciding between a simple setup and a complex CO2-injected system.', 'Aquatic', '🌿', 10, ARRAY['plants','tech','setup','training']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T21:48:00Z'::timestamptz, '2026-05-14T21:48:00Z'::timestamptz),
('Signs of Freshwater Ich and How to Treat It', 'Ich is a common parasite that looks like small grains of salt on a fish''s body. If spotted, increase the tank temperature gradually to 30°C to speed up the parasite''s life cycle and treat with aquarium salt or specialized medication. Prompt action is necessary to prevent a total tank wipeout.', 'How to identify and cure ''White Spot Disease'' before it spreads.', 'Aquatic', '🏥', 8, ARRAY['health','disease','medicine','safety']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T21:50:00Z'::timestamptz, '2026-05-14T21:50:00Z'::timestamptz),
('Betta Fish and Tank Mate Compatibility', 'While male Bettas are known for aggression, they can often live with peaceful bottom-dwellers like Corydoras or invertebrates like Nerite snails. Avoid fin-nippers like Tetras or other flashy fish that a Betta might perceive as a rival. Always have a backup plan in case your Betta prefers the solo life.', 'Can Bettas live with others? A guide to peaceful community living for Siamese Fighting Fish.', 'Aquatic', '🐟', 7, ARRAY['betta','compatibility','behavior','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:00:00Z'::timestamptz, '2026-05-14T22:00:00Z'::timestamptz),
('Mastering Water Changes: The 25% Rule', 'Removing 25% of your tank water weekly is the most effective way to export nitrates and replenish essential minerals. Using a gravel vacuum helps pull debris from the substrate. Always remember to treat your new tap water with a de-chlorinator before adding it to the tank to protect your beneficial bacteria.', 'Why consistent, partial water changes are the secret to a crystal-clear aquarium.', 'Aquatic', '🪣', 6, ARRAY['maintenance','water quality','training','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:05:00Z'::timestamptz, '2026-05-14T22:05:00Z'::timestamptz),
('The Benefits of Floating Plants', 'Floating plants are incredible nitrate sponges, helping to keep your water clean by absorbing excess nutrients. Their long, trailing roots provide excellent hiding spots for fry and shrimp. Be sure to thin them out regularly, as they can quickly cover the surface and block light from reaching plants below.', 'How plants like Frogbit and Salvinia act as natural filters and provide shade.', 'Aquatic', '🌿', 5, ARRAY['plants','filtration','aquascape','health']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:10:00Z'::timestamptz, '2026-05-14T22:10:00Z'::timestamptz),
('Understanding Aquarium pH and Hardness', 'pH measures the acidity of your water, while hardness (GH/KH) refers to mineral content. Most tropical fish thrive in a stable pH between 6.5 and 7.5. Sudden fluctuations are far more dangerous than slightly ''off'' parameters, so avoid using chemical adjusters unless absolutely necessary for sensitive species.', 'A deep dive into water chemistry and how it affects your fish''s comfort.', 'Aquatic', '🧪', 9, ARRAY['chemistry','water quality','safety','health']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:15:00Z'::timestamptz, '2026-05-14T22:15:00Z'::timestamptz),
('Feeding Your Bottom Dwellers Correctly', 'Bottom dwellers are often misunderstood as ''scavengers'' that can live on leftovers alone. In reality, they require dedicated sinking pellets or wafers to thrive. Feed them shortly after turning off the lights to give them a chance to eat without competition from faster-moving surface feeders.', 'Ensuring your Corydoras and Loaches don''t go hungry in a community tank.', 'Aquatic', '🐌', 4, ARRAY['food','behavior','fish','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:20:00Z'::timestamptz, '2026-05-14T22:20:00Z'::timestamptz),
('What to Expect When Your Fish are Spawning', 'Spawning behavior often includes chasing, nest building, or clearing a flat surface like a leaf or rock. Once eggs are laid, some parents (like Cichlids) are fiercely protective, while others may eat their own young. Using a separate breeder box or a densely planted area is key to ensuring the survival of the fry.', 'Identifying the signs of breeding behavior and how to protect the fry.', 'Aquatic', '🥚', 8, ARRAY['breeding','behavior','what to expect','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:25:00Z'::timestamptz, '2026-05-14T22:25:00Z'::timestamptz),
('Choosing the Right Lighting for Planted Tanks', 'Aquarium plants require specific light spectrums, typically between 6500K and 7000K, to photosynthesize effectively. A common mistake is leaving lights on too long; a consistent 6-8 hour photoperiod is usually sufficient. High-intensity LED systems allow for dimming and sunrise/sunset effects, reducing stress on your fish.', 'Understanding PAR, Kelvin, and photoperiods to achieve lush plant growth without algae.', 'Aquatic', '💡', 10, ARRAY['lighting','plants','tech','maintenance']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:30:00Z'::timestamptz, '2026-05-14T22:30:00Z'::timestamptz),
('Pressurized CO2: A Game Changer for Aquascapers', 'CO2 injection allows plants to grow faster and more robustly, often outcompeting algae for nutrients. A basic system includes a cylinder, regulator, and a diffuser. It is critical to monitor levels with a drop checker to ensure you aren''t gassing your fish, as excess CO2 can lead to oxygen deprivation and pH crashes.', 'Why injecting carbon dioxide is the secret to those vibrant ''Red'' aquatic plants.', 'Aquatic', '🫧', 12, ARRAY['CO2','plants','tech','safety']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:35:00Z'::timestamptz, '2026-05-14T22:35:00Z'::timestamptz),
('Mechanical vs. Biological vs. Chemical Filtration', 'Mechanical filtration removes visible debris, biological filtration houses bacteria that process waste, and chemical filtration (like carbon) removes odors and toxins. For most setups, biological filtration is the most vital. Never wash your filter media in tap water; use tank water to avoid killing the beneficial bacteria.', 'Understanding the three pillars of a clean tank and why you need all of them.', 'Aquatic', '🌀', 8, ARRAY['filtration','maintenance','water quality','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:40:00Z'::timestamptz, '2026-05-14T22:40:00Z'::timestamptz),
('The Dangers of New Tank Syndrome', 'New Tank Syndrome occurs when the biological filter isn''t strong enough to handle the waste produced by fish, leading to deadly ammonia spikes. You may notice cloudy water or gasping fish. To avoid this, ''fishless cycling'' is recommended, where you build up bacteria before adding any live animals to the environment.', 'How to identify and survive the first month of a new aquarium setup.', 'Aquatic', '☁️', 9, ARRAY['cycling','health','safety','what to expect']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:45:00Z'::timestamptz, '2026-05-14T22:45:00Z'::timestamptz),
('Substrate Secrets: Sand, Gravel, or Soil?', 'Root-heavy plants like Amazon Swords require nutrient-rich aqua soils, while bottom-dwellers like Corydoras prefer smooth sand to protect their delicate barbels. Gravel is excellent for biological filtration but can trap waste more easily. Consider your final ''vision'' before committing, as changing substrate later is a major task.', 'Choosing the right floor for your tank based on your plants and inhabitants.', 'Aquatic', '🏖️', 7, ARRAY['substrate','setup','plants','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:50:00Z'::timestamptz, '2026-05-14T22:50:00Z'::timestamptz),
('Algae Management: Identifying Green Spot vs. BBA', 'Green Spot Algae often indicates low phosphates, while Black Brush Algae (BBA) is usually linked to fluctuating CO2 levels. Algae isn''t just an eyesore; it''s a signal that your light, nutrients, and CO2 are out of sync. Regular manual removal and adjusting your ferts can help bring the ecosystem back to harmony.', 'How to troubleshoot common algae outbreaks by looking at your tank''s balance.', 'Aquatic', '🦠', 11, ARRAY['algae','maintenance','health','training']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:55:00Z'::timestamptz, '2026-05-14T22:55:00Z'::timestamptz),
('Deworming Protocol for Puppies in India', 'Intestinal worms are extremely common in puppies across India. A standard protocol usually begins at 2 weeks of age, repeated every fortnight until 3 months. Common parasites include roundworms and hookworms. Consult your veterinarian for a broad-spectrum dewormer suitable for your puppy''s weight and breed.', 'Protecting your new pup from common intestinal parasites prevalent in tropical climates.', 'Canine', '💊', 6, ARRAY['dogs','puppy care','health','India']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:00:00Z'::timestamptz, '2026-05-14T22:00:00Z'::timestamptz),
('The Dangers of Lilies for Cats', 'Lilies are highly toxic to cats; even a small amount of pollen or water from the vase can cause acute kidney failure. Symptoms include vomiting, lethargy, and loss of appetite. If you suspect your cat has come into contact with any part of a lily, seek emergency veterinary care immediately.', 'Why this common household flower is a lethal threat to your feline friends.', 'Feline', '🌸', 5, ARRAY['cats','safety','emergency','health']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:05:00Z'::timestamptz, '2026-05-14T22:05:00Z'::timestamptz),
('Maintaining Water Clarity in Outdoor Ponds', 'Outdoor ponds face unique challenges like UV exposure and falling leaves. Installing a UV clarifier can help eliminate green water caused by suspended algae. Additionally, adding floating plants like lilies or water lettuce provides shade, which naturally inhibits algae growth while providing cover for your fish.', 'Dealing with algae and debris in a garden aquatic environment.', 'Aquatic', '⛲', 8, ARRAY['pond','maintenance','algae','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:10:00Z'::timestamptz, '2026-05-14T22:10:00Z'::timestamptz),
('Understanding Night Frights in Cockatiels', 'Cockatiels are prone to ''night frights,'' where they thrash around the cage in a panic. This is often triggered by shadows or sudden noises. Using a dim nightlight near the cage and ensuring the cage is partially covered can help your bird feel secure and prevent wing injuries during the night.', 'How to manage sudden episodes of panic in your bird during the night.', 'Avian', '🌙', 6, ARRAY['birds','cockatiels','behavior','safety']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:15:00Z'::timestamptz, '2026-05-14T22:15:00Z'::timestamptz),
('The Ideal Diet for Guinea Pigs', 'Guinea pigs cannot produce their own Vitamin C, so they must get it through their diet via fresh bell peppers or fortified pellets. Timothy hay should make up 80% of their intake to ensure proper digestion and dental wear. Avoid sugary treats or ''muesli'' mixes which can lead to obesity and dental disease.', 'Why Vitamin C and high-quality hay are non-negotiable for these small pets.', 'Small Pet', '🥕', 7, ARRAY['guinea pigs','food','nutrition','health']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:20:00Z'::timestamptz, '2026-05-14T22:20:00Z'::timestamptz),
('Pet Proofing Your Home: A Universal Checklist', 'Start by securing all trash cans and hiding exposed electrical wires. Check your houseplants against toxicity lists and ensure all cleaning chemicals are stored in high, locked cabinets. For small pets or puppies, ''crawl'' through your home at their eye level to spot small objects they might swallow.', 'General safety measures every pet owner should take before bringing a new animal home.', 'General', '🛡️', 10, ARRAY['safety','new pet','home','what to expect']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:25:00Z'::timestamptz, '2026-05-14T22:25:00Z'::timestamptz),
('Socializing Your Puppy: The Golden Window', 'The socialization window is a brief period where puppies are most receptive to new experiences. Safely expose your pup to different sounds, surfaces, and people. Since full vaccination is pending, avoid high-traffic dog parks, but consider ''puppy parties'' with other healthy, vaccinated dogs to build social skills.', 'Why the first 16 weeks are critical for developing a confident and friendly dog.', 'Canine', '🐾', 8, ARRAY['dogs','puppy','training','behavior']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:30:00Z'::timestamptz, '2026-05-14T22:30:00Z'::timestamptz),
('The Importance of Vertical Space for Cats', 'Cats are three-dimensional animals that feel safer when they can observe their environment from a height. Providing cat trees or wall-mounted shelves expands their territory without needing more floor space. This is especially important in multi-cat households to allow individuals to escape conflict and rest peacefully.', 'How cat trees and shelves can reduce anxiety and territory disputes.', 'Feline', '🧗', 6, ARRAY['cats','life','home','behavior']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:35:00Z'::timestamptz, '2026-05-14T22:35:00Z'::timestamptz),
('Managing Algae with Nerite Snails', 'Nerite snails are voracious algae eaters that won''t overpopulate your tank because they require brackish water to breed. They are excellent at cleaning glass and hardscape without damaging delicate plants. They are peaceful inhabitants that fit perfectly into almost any community tank setup.', 'Why these snails are the perfect peaceful addition to a planted aquarium.', 'Aquatic', '🐌', 5, ARRAY['snails','algae','maintenance','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:40:00Z'::timestamptz, '2026-05-14T22:40:00Z'::timestamptz),
('Safe Foraging Toys for Small Mammals', 'Foraging is a natural instinct for small mammals. Hide treats inside cardboard tubes or hay-stuffed boxes to encourage them to work for their food. This mental stimulation prevents boredom-based behaviors like cage chewing. Always ensure the materials used are unprinted and free of toxic glues.', 'How to keep your rabbits and hamsters mentally stimulated through play.', 'Small Pet', '🎾', 7, ARRAY['rabbits','hamsters','training','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:45:00Z'::timestamptz, '2026-05-14T22:45:00Z'::timestamptz),
('Recognizing Signs of Illness in Birds', 'In the wild, showing weakness makes a bird a target, so they are masters of hiding illness. Key signs to watch for include fluffed feathers, changes in droppings, sitting on the bottom of the cage, or a decrease in vocalization. If you notice any of these, contact an avian veterinarian immediately.', 'Because birds hide their symptoms, knowing these subtle signs can save their lives.', 'Avian', '🏥', 9, ARRAY['birds','health','safety','what to expect']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:50:00Z'::timestamptz, '2026-05-14T22:50:00Z'::timestamptz),
('Travel Tips: Flying with Your Pet', 'Traveling by air requires extensive preparation, including airline-approved crates and specific health certifications. Research the quarantine laws of your destination well in advance. For the comfort of your pet, familiarize them with their travel crate weeks before the trip to reduce anxiety during the flight.', 'Navigating the logistics and safety requirements of air travel with animals.', 'General', '✈️', 11, ARRAY['travel','safety','life','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T22:55:00Z'::timestamptz, '2026-05-14T22:55:00Z'::timestamptz),
('Natural Remedies for Dog Paw Care in Monsoons', 'The monsoon brings moisture that can lead to ''interdigital dermatitis'' in dogs. Always dry your pet''s paws thoroughly after walks. A simple diluted apple cider vinegar rinse can help maintain the natural pH of the skin and discourage fungal growth. If paws become red or inflamed, consult a vet for medicated powders.', 'How to prevent fungal infections and irritation during India''s rainy season.', 'Canine', '🐾', 5, ARRAY['dogs','monsoon','health','India']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:00:00Z'::timestamptz, '2026-05-14T23:00:00Z'::timestamptz),
('Hydration Hacks for Finicky Cats', 'Cats often have a low thirst drive, which can lead to urinary tract issues. Try adding a little water or ''tuna juice'' to their wet food. Switching to a recirculating water fountain can also encourage drinking, as many cats prefer running water over a stagnant bowl. Ensure water bowls are placed away from litter boxes.', 'Creative ways to increase your cat''s water intake to prevent kidney issues.', 'Feline', '💧', 6, ARRAY['cats','food','health','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:05:00Z'::timestamptz, '2026-05-14T23:05:00Z'::timestamptz),
('Low-Light Plants for Your First Aquarium', 'If you are just starting, look for Anubias, Java Fern, and Cryptocoryne. These plants thrive in low light and don''t require CO2 injection. Anubias and Java Fern should be tied to rocks or driftwood rather than buried in substrate, as their rhizomes will rot if covered. They are perfect for adding greenery with minimal effort.', 'The best ''unkillable'' plants for beginners without expensive lighting setups.', 'Aquatic', '🌿', 7, ARRAY['aquarium','plants','beginner','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:10:00Z'::timestamptz, '2026-05-14T23:10:00Z'::timestamptz),
('The Dangers of Teflon/PTFE for Birds', 'When overheated, non-stick coatings release odorless fumes that are highly toxic to avian respiratory systems. This can cause ''Teflon toxicity,'' often resulting in sudden death. Switch to stainless steel, cast iron, or ceramic cookware to ensure your bird''s safety, and always keep the kitchen well-ventilated.', 'Why your non-stick cookware could be a silent killer for your parrot.', 'Avian', '🍳', 8, ARRAY['birds','safety','home','health']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:15:00Z'::timestamptz, '2026-05-14T23:15:00Z'::timestamptz),
('Grooming Your Long-Haired Rabbit', 'Long-haired rabbits require daily brushing to prevent mats and ''wool block,'' a dangerous condition where ingested hair clogs the digestive tract. Use a slicker brush and a wide-toothed comb to gently reach the undercoat. If you find a stubborn mat, never use scissors near the skin; use a mat splitter or consult a professional groomer.', 'Preventing painful matting and wool block in breeds like Angoras.', 'Small Pet', '🐰', 7, ARRAY['rabbits','grooming','health','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:20:00Z'::timestamptz, '2026-05-14T23:20:00Z'::timestamptz),
('Creating a Pet Emergency Evacuation Plan', 'In an emergency, every second counts. Your pet''s evacuation kit should include a week''s supply of food, bottled water, copies of vaccination records, and a sturdy carrier. Ensure your pet is microchipped and wearing a collar with an ID tag. Practice your exit route so both you and your pet remain calm during a real crisis.', 'Being prepared for natural disasters: what to pack in your pet''s ''Go Bag''.', 'General', '🚨', 10, ARRAY['safety','emergency','training','what to expect']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:25:00Z'::timestamptz, '2026-05-14T23:25:00Z'::timestamptz),
('Recall Training: Teaching Your Dog to Come', 'A reliable recall can save your dog''s life. Start in a low-distraction environment, using a high-value treat every time they return to you. Never call your dog to you for something they dislike (like a bath), as this creates a negative association. Keep it positive, and slowly increase the level of distraction as they improve.', 'The most important safety command every dog must master.', 'Canine', '📢', 9, ARRAY['dogs','training','safety','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:30:00Z'::timestamptz, '2026-05-14T23:30:00Z'::timestamptz),
('Why Cats Knead: The ''Making Biscuits'' Mystery', 'Kneading is an instinctive behavior that begins in kittenhood to stimulate milk flow from the mother. In adult cats, it''s often a sign of comfort, contentment, and marking territory with the scent glands in their paws. If your cat kneads you, take it as a compliment—they feel safe and bonded with you.', 'Exploring the science and instinct behind this adorable feline behavior.', 'Feline', '🐾', 4, ARRAY['cats','behavior','life','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:35:00Z'::timestamptz, '2026-05-14T23:35:00Z'::timestamptz),
('How to Safely Acclimatize New Fish', 'Never just dump new fish into your tank. Use the ''drip acclimation'' method: float the bag to match temperatures, then slowly add small amounts of tank water to the bag over 30-60 minutes. This allows the fish to adjust to the new pH and hardness levels gradually, significantly reducing the risk of stress-related illness.', 'Preventing shock when introducing new inhabitants to your aquarium.', 'Aquatic', '🌡️', 8, ARRAY['aquarium','safety','maintenance','what to expect']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:40:00Z'::timestamptz, '2026-05-14T23:40:00Z'::timestamptz),
('Enrichment Ideas for Bored Parrots', 'Parrots are highly intelligent and need mental exercise. Rotate their toys weekly to keep them fresh. Introduce ''puzzle feeders'' that require them to manipulate objects to get a treat. Even playing music or leaving a bird-safe TV program on can provide auditory and visual stimulation that prevents destructive behaviors like feather plucking.', 'Creative ways to keep your bird''s intelligent mind active and engaged.', 'Avian', '🧩', 7, ARRAY['birds','training','life','behavior']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:45:00Z'::timestamptz, '2026-05-14T23:45:00Z'::timestamptz),
('The Dust Bath: Essential Care for Chinchillas', 'Chinchillas should never be bathed in water, as their dense fur traps moisture and can lead to fungal infections. Instead, they require a ''dust bath'' 2-3 times a week using specialized volcanic ash. The dust absorbs oils and dirt, keeping their coat soft and healthy. Limit each session to 15 minutes to prevent their skin from drying out.', 'Why water is bad for chinchilla fur and how to manage their hygiene.', 'Small Pet', '☁️', 6, ARRAY['chinchillas','grooming','health','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:50:00Z'::timestamptz, '2026-05-14T23:50:00Z'::timestamptz),
('Budgeting for a New Pet: The Hidden Costs', 'The true cost of a pet includes recurring expenses like premium food, annual vaccinations, and flea/tick prevention. Don''t forget to set aside an ''emergency fund'' for unexpected vet visits or professional grooming. Factor in these costs early to ensure you can provide a high quality of life for your new companion for years to come.', 'Planning for more than just the adoption fee—what you really need to save.', 'General', '💰', 11, ARRAY['finance','new pet','life','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-14T23:55:00Z'::timestamptz, '2026-05-14T23:55:00Z'::timestamptz),
('Caring for Your Senior Dog: Joint Health', 'As dogs age, joint wear and tear can lead to decreased mobility. Look for stiffness after naps or a reluctance to climb stairs. Supplementing their diet with Glucosamine and Chondroitin can help, but simple home changes like adding non-slip rugs and orthopedic beds provide immediate relief for their aching limbs.', 'How to spot signs of arthritis and adapt your home for an aging canine.', 'Canine', '🦴', 8, ARRAY['dogs','senior care','health','life']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T00:00:00Z'::timestamptz, '2026-05-15T00:00:00Z'::timestamptz),
('The Science of Cat Scratching', 'Scratching is a biological necessity for cats to shed old claw sheaths and mark territory via scent glands in their paws. To save your furniture, provide both vertical and horizontal scratching posts made of sisal or cardboard. Place them near their favorite sleeping spots to encourage use right after they wake up.', 'Why cats need to scratch and how to redirect them away from your sofa.', 'Feline', '🐈', 6, ARRAY['cats','behavior','home','training']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T00:05:00Z'::timestamptz, '2026-05-15T00:05:00Z'::timestamptz),
('Trimming Aquatic Plants for Better Growth', 'Regular trimming prevents stem plants from becoming leggy and allows light to reach the bottom leaves. For stem plants, cut just above a node to encourage branching. For ''runners'' like Vallisneria, thin out the daughter plants to prevent overcrowding. Use sharp aquascaping shears to ensure clean cuts that heal quickly.', 'Master the art of the ''bushy'' look by knowing where and when to cut.', 'Aquatic', '✂️', 7, ARRAY['plants','maintenance','aquascape','generic']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T00:10:00Z'::timestamptz, '2026-05-15T00:10:00Z'::timestamptz),
('Avian Respiratory Health: Air Quality Tips', 'Birds have incredibly efficient but fragile respiratory systems. Beyond Teflon, avoid using scented candles, incense, or harsh cleaning sprays near your bird''s room. If you notice wheezing or open-beak breathing, it is a medical emergency. Consider a high-quality HEPA air purifier to keep their environment dander and toxin-free.', 'Protecting your bird''s sensitive lungs from household pollutants.', 'Avian', '🌬️', 9, ARRAY['birds','health','safety','home']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T00:15:00Z'::timestamptz, '2026-05-15T00:15:00Z'::timestamptz),
('Taming a Skittish Hamster', 'Never grab a new hamster from above, as this mimics a predator''s attack. Start by placing your hand in the cage with a treat and let them sniff you. Rubbing a tissue on your skin and placing it in their cage helps them associate your scent with safety. It may take weeks, but a tame hamster is a much more rewarding companion.', 'Building trust with your small pet through patience and scent association.', 'Small Pet', '🐹', 7, ARRAY['hamster','training','bonding','what to expect']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T00:20:00Z'::timestamptz, '2026-05-15T00:20:00Z'::timestamptz),
('Microchipping 101: Why It’s Better Than a Tag', 'While collars and tags can fall off or be removed, a microchip is a permanent form of identification about the size of a grain of rice. It is injected under the skin and can be scanned by any vet or shelter. Crucially, remember to keep your contact information updated in the national database for the chip to be effective.', 'Ensuring your pet can always find their way home with permanent identification.', 'General', '📡', 5, ARRAY['safety','new pet','life','health']::text[], NULL, true, 'Petosauras Team', 0, '2026-05-15T00:25:00Z'::timestamptz, '2026-05-15T00:25:00Z'::timestamptz)
) AS v(title, content, summary, category, emoji, read_time_minutes, tags, thumbnail_url, is_published, author_name, view_count, created_at, updated_at)
